    Return True if buildings in a row have unique length, False otherwise.

    >>> check_uniqueness_in_rows(['***21**', '412453*', '423145*',\
         '*543215', '*35214*', '*41532*', '*2*1***'])
    True
    >>> check_uniqueness_in_rows(['***21**', '452453*', '423145*',\
         '*543215', '*35214*', '*41532*', '*2*1***'])
    False
    >>> check_uniqueness_in_rows(['***21**', '412453*', '423145*',\
         '*553215', '*35214*', '*41532*', '*2*1***'])
    False
    """
def check_uniqueness_in_rows(board: list) -> object {
    for row in board[1:-1] {
        set_row = `set(row[1:-1]);
        if (len(row[1:-1]) != len(set_row)) {
            return False;
        }
    }
    return True;
}

"""
  Return the input number if its odd,
  or return input number + 1 if its even or zero.
  """
def make_odd(number: Any) -> object {
    if (number == 0) {
        number += 1;
    }
    if ((number % 2) == 0) {
        number += -1;
    }
    return number;
}

